#[tokio::test]
async fn public_membership_module_states_are_distinct_and_opaque() {
    let mut runner = TestRunner::setup().await;
    let site = run_endpoint!(runner, site_get, json!({"site": "scp-wiki"}))
        .expect("seeded mirror site should exist")
        .site;
    let source = concat!(
        "[[module Join button=\"one\" button=\"two\" class=\"membership-join-fixture\"]]\n",
        "[[module JOIN BUTTON='single-quoted-is-ignored']]\n",
        "[[module Join button=\"\"]]\n",
        "[[module MembershipApply]]\n",
        "[[module MembershipByPassword]]\n",
        "[[module MembershipEmailInvitation token=\"invitation-secret\"]]\n",
        "[[module AnonymousNotificationsUnsubscribe token=\"unsubscribe-secret\"]]\n",
        "[[module SendInvitations]]",
    );

    runner.set_request_context(RequestContext {
        site_id: Some(site.site_id),
        ..Default::default()
    });
    let anonymous = run_endpoint!(
        runner,
        wikidot_page_preview,
        json!({
            "site_id": site.site_id,
            "title": "Membership public states",
            "wikitext": source,
        }),
    );

    for expected in [
        r#"<div class="membership-join-fixture"><a href="javascript:;" onclick="WIKIDOT.page.listeners.join(event, 'unified')">two</a></div>"#,
        r#"<div class="join-box"><a href="javascript:;" onclick="WIKIDOT.page.listeners.join(event, 'unified')">Join</a></div>"#,
        "You need to have a Wikidot.com account and be signed to apply for membership.",
        "Membership via password is not enabled for this site.",
        "Sorry, the invitation could not be found.",
        "Invalid indentification token.",
        "Inviting users has been disabled due to severe abuse.",
    ] {
        assert!(
            anonymous.body.contains(expected),
            "anonymous preview should contain {expected:?}:\n{}",
            anonymous.body,
        );
    }
    for secret in ["invitation-secret", "unsubscribe-secret"] {
        assert!(
            !anonymous.body.contains(secret),
            "opaque token failures must not reflect {secret:?}:\n{}",
            anonymous.body,
        );
    }
    assert!(
        anonymous.membership_actions.is_empty(),
        "PagePreview must render exact Join DOM without issuing a saved-page mutation binding",
    );

    runner.set_request_context(RequestContext {
        user_id: Some(ADMIN_USER_ID),
        site_id: Some(site.site_id),
        ..Default::default()
    });
    let member = run_endpoint!(
        runner,
        wikidot_page_preview,
        json!({
            "site_id": site.site_id,
            "title": "Membership member states",
            "wikitext": source,
        }),
    );
    assert!(
        !member.body.contains("membership-join-fixture"),
        "a current site member must not see Join:\n{}",
        member.body,
    );
    assert!(member.membership_actions.is_empty());
}

fn set_mutation_request_context(
    runner: &mut TestRunner,
    user_id: i64,
    site_id: i64,
    page_reference: Reference<'static>,
) {
    runner.set_request_context(RequestContext {
        session: None,
        user_id: Some(user_id),
        site_id: Some(site_id),
        page_reference: Some(page_reference),
    });
}

async fn import_cacheable_page_attribution_fixture(
    runner: &mut TestRunner,
    site_id: i64,
    label: &str,
) -> (i64, String) {
    let run_id = cuid();
    let page_id = rand::random_range(1_700_000_000_i64..1_799_999_999_i64);
    let revision_id = rand::random_range(1_800_000_000_i64..1_899_999_999_i64);
    let slug = format!("page-attribution-cache-{label}-{run_id}");

    set_mutation_request_context(
        runner,
        ADMIN_USER_ID,
        site_id,
        Reference::Slug(Cow::Owned(slug.clone())),
    );
    run_endpoint!(
        runner,
        import_wikidot_page,
        json!({
            "page_id": page_id,
            "site_id": site_id,
            "created_at": "1970-01-01T00:00:00Z",
            "slug": slug,
            "locked": false,
            "discussion_thread_id": null,
            "ip_address": common::IP_ADDRESS,
        }),
    );
    run_endpoint!(
        runner,
        import_wikidot_page_revision,
        json!({
            "revision_id": revision_id,
            "revision_type": "create",
            "created_at": time::OffsetDateTime::UNIX_EPOCH,
            "updated_at": null,
            "revision_number": 0,
            "page_id": page_id,
            "site_id": site_id,
            "user_id": ADMIN_USER_ID,
            "wikitext": format!("Imported attribution cache {label} fixture."),
            "comments": format!("import page attribution cache {label} fixture"),
            "title": format!("Page attribution cache {label} fixture"),
            "slug": slug,
            "tags": [],
        }),
    );
    runner
        .context()
        .run_post_commit_actions()
        .await
        .expect("import post-commit actions should complete before cache assertions");

    (page_id, slug)
}

struct CachedAttributionArticle {
    attributions: Vec<PageAttribution>,
    cache_key: String,
    fence: String,
}

async fn load_cached_attribution_article(
    runner: &mut TestRunner,
    site_id: i64,
    slug: &str,
) -> CachedAttributionArticle {
    runner.set_request_context(RequestContext {
        site_id: Some(site_id),
        ..Default::default()
    });
    match run_endpoint!(
        runner,
        article_view,
        json!({
            "site_id": site_id,
            "session_token": null,
            "route": {"slug": slug, "extra": ""},
            "locales": ["en-US", "en"],
        }),
    ) {
        GetArticleViewOutput {
            page: GetPageViewOutput::Found { attributions, .. },
            article_page_cache_key: Some(cache_key),
            public_content_cache_fence: Some(fence),
            ..
        } => CachedAttributionArticle {
            attributions,
            cache_key,
            fence,
        },
        other => panic!("expected a cacheable imported article, got {other:?}"),
    }
}

