    const PRIVATE_PAGE_CATEGORY: &str = "forum-read-model-private";
    const PRIVATE_PAGE_SLUG: &str = "fixture-forum-read-model-private";
    make_listpages_test_category_admin_only(&runner, site_id, PRIVATE_PAGE_CATEGORY)
